//! Formats generated code and writes it, or compares it with what is checked in.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

use crate::GenResult;

/// One generated source file.
pub struct GeneratedFile {
    /// Its path under `crates/asana-openapi/src/generated/`, for example `models/tasks.rs`.
    pub path: PathBuf,
    /// Its items. The "GENERATED, do not edit" header and formatting are added by [`finish`].
    pub tokens: proc_macro2::TokenStream,
}

/// What [`finish`] does with the files.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Mode {
    /// Replace the directory's contents.
    Write,
    /// Change nothing; fail when the directory differs.
    Check,
}

const HEADER: &str = "// GENERATED by `cargo xtask gen` from spec/asana_oas.yaml. Do not edit.\n\n";

/// Formats every file with `prettyplease`, then writes the set (removing files no longer
/// generated) or reports the first difference. Only files whose first path component is in
/// `owned` are ever removed or reported stale, so one half of the generator can run alone.
pub fn finish(
    directory: &Path,
    files: Vec<GeneratedFile>,
    mode: Mode,
    owned: &[&str],
) -> GenResult<String> {
    let mut rendered = BTreeMap::new();
    for file in files {
        let parsed: syn::File = syn::parse2(file.tokens)
            .map_err(|error| format!("{} is not valid Rust: {error}", file.path.display()))?;
        let text = rustfmt(
            directory,
            &format!("{HEADER}{}", prettyplease::unparse(&parsed)),
        )
        .map_err(|error| format!("formatting {}: {error}", file.path.display()))?;
        if rendered.insert(file.path.clone(), text).is_some() {
            return Err(format!("{} was generated twice", file.path.display()));
        }
    }
    let existing: Vec<PathBuf> = existing_files(directory)?
        .into_iter()
        .filter(|path| {
            path.components()
                .next()
                .is_some_and(|first| owned.iter().any(|name| first.as_os_str() == *name))
        })
        .collect();
    if let Some(stray) = rendered.keys().find(|path| {
        !path
            .components()
            .next()
            .is_some_and(|first| owned.iter().any(|name| first.as_os_str() == *name))
    }) {
        return Err(format!(
            "{} is outside the paths this run owns",
            stray.display()
        ));
    }
    match mode {
        Mode::Check => {
            for (path, text) in &rendered {
                let on_disk = fs::read_to_string(directory.join(path)).unwrap_or_default();
                if &on_disk != text {
                    return Err(format!(
                        "{} is out of date: run `cargo xtask gen` and commit the result",
                        path.display()
                    ));
                }
            }
            if let Some(stale) = existing.iter().find(|path| !rendered.contains_key(*path)) {
                return Err(format!(
                    "{} is no longer generated: run `cargo xtask gen`",
                    stale.display()
                ));
            }
            Ok(format!("{} generated files are up to date", rendered.len()))
        }
        Mode::Write => {
            for stale in existing.iter().filter(|path| !rendered.contains_key(*path)) {
                fs::remove_file(directory.join(stale))
                    .map_err(|error| format!("removing {}: {error}", stale.display()))?;
            }
            for (path, text) in &rendered {
                let target = directory.join(path);
                if let Some(parent) = target.parent() {
                    fs::create_dir_all(parent)
                        .map_err(|error| format!("creating {}: {error}", parent.display()))?;
                }
                fs::write(&target, text)
                    .map_err(|error| format!("writing {}: {error}", target.display()))?;
            }
            Ok(format!("wrote {} generated files", rendered.len()))
        }
    }
}

/// Runs `rustfmt` over generated source with the repository's own configuration, so the
/// checked-in files are exactly what `cargo fmt` would leave and `gen --check` and
/// `cargo fmt --check` can never disagree. `prettyplease` first, because rustfmt alone gives up on
/// very long token lines.
fn rustfmt(directory: &Path, source: &str) -> GenResult<String> {
    use std::io::Write;
    use std::process::{Command, Stdio};

    // `directory` is `<root>/crates/asana-openapi/src/generated`.
    let root = directory.ancestors().nth(4).unwrap_or(directory);
    let mut child = Command::new("rustfmt")
        .arg("--edition")
        .arg("2024")
        .arg("--config-path")
        .arg(root.join("rustfmt.toml"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|error| format!("could not start rustfmt: {error}"))?;
    let mut stdin = child.stdin.take().ok_or("rustfmt has no stdin")?;
    let input = source.to_owned();
    let writer = std::thread::spawn(move || stdin.write_all(input.as_bytes()));
    let output = child
        .wait_with_output()
        .map_err(|error| format!("rustfmt did not finish: {error}"))?;
    writer
        .join()
        .map_err(|_| "the thread feeding rustfmt panicked".to_owned())?
        .map_err(|error| format!("writing to rustfmt: {error}"))?;
    if !output.status.success() {
        return Err(format!(
            "rustfmt refused it: {}",
            String::from_utf8_lossy(&output.stderr).trim()
        ));
    }
    String::from_utf8(output.stdout)
        .map_err(|error| format!("rustfmt wrote invalid UTF-8: {error}"))
}

/// Every `.rs` file under `directory`, relative to it.
fn existing_files(directory: &Path) -> GenResult<Vec<PathBuf>> {
    fn walk(root: &Path, directory: &Path, found: &mut Vec<PathBuf>) -> std::io::Result<()> {
        if !directory.exists() {
            return Ok(());
        }
        for entry in fs::read_dir(directory)? {
            let path = entry?.path();
            if path.is_dir() {
                walk(root, &path, found)?;
            } else if path.extension().is_some_and(|extension| extension == "rs") {
                found.push(path.strip_prefix(root).unwrap_or(&path).to_path_buf());
            }
        }
        Ok(())
    }
    let mut found = Vec::new();
    walk(directory, directory, &mut found)
        .map_err(|error| format!("reading {}: {error}", directory.display()))?;
    found.sort();
    Ok(found)
}
